import { MeshStandardNodeMaterial, Color, Group } from 'three/webgpu';
import { uv, smoothstep, mix } from 'three/tsl';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new Group();

  // === COLORS ===
  const colors = {
    background: new Color('#0b0b10'),
    surface: new Color('#111117'),
    ink: new Color('#16161d'),
    paper: new Color('#e8ecf2'),
    accent: new Color('#ff2a38'),
    hairline: new Color('#23232b')
  };

  // === RIBBON BASE PLANE ===
  const ribbonGeom = new THREE.PlaneGeometry(7.0, 0.35);

  const ribbonMat = new MeshStandardNodeMaterial({
    color: colors.surface,
    roughness: 0.6,
    metalness: 0.2,
    emissive: new Color(0x000000),
    transparent: true,
    side: THREE.DoubleSide
  });

  // TSL nodes for edge fades and hairlines
  const uvNode = uv();

  // Edge fade mask: 0.6 units wide at both ends
  const fadeWidthNorm = 0.6 / 7.0;
  const leftFade = smoothstep(0.0, fadeWidthNorm, uvNode.x);
  const rightFadeValue = smoothstep(1.0 - fadeWidthNorm, 1.0, uvNode.x);
  const rightFade = mix(1.0, 0.0, rightFadeValue);
  const edgeMask = leftFade.mul(rightFade);

  // Hairline detection: top and bottom 0.006-unit lines
  const hairlineThickness = 0.006 / 0.35;
  const topHairline = smoothstep(1.0 - hairlineThickness, 1.0, uvNode.y);
  const bottomHairline = smoothstep(0.0, hairlineThickness, uvNode.y);
  const hairlineMask = topHairline.add(bottomHairline).clamp(0.0, 1.0);

  // Apply TSL nodes to material
  ribbonMat.colorNode = mix(colors.surface, colors.hairline, hairlineMask);
  ribbonMat.alphaNode = edgeMask;

  const ribbon = new THREE.Mesh(ribbonGeom, ribbonMat);
  group.add(ribbon);

  // === CONTENT LAYER (text + ticks) ===
  const contentGroup = new Group();
  contentGroup.position.z = 0.02; // Float above ribbon

  const entries = [
    'CAL NA-01 BEAT 28800 VPH',
    'POWER RESERVE 72H',
    'CASE 40.5 MM 904L',
    'REF 5811 IN STOCK',
    'WAITLIST 1204',
    'NEXT FITTING JUL 18'
  ];

  // Tick separator material
  const tickMat = new MeshStandardNodeMaterial({
    color: colors.accent,
    emissive: colors.accent,
    emissiveIntensity: 1.5,
    roughness: 0.5,
    metalness: 0.1
  });

  const tickWidth = 0.02 * 7.0; // 0.14 scene units
  const tickHeight = 0.14 * 0.35; // ~0.049 scene units
  const gapSize = 0.5;

  // Layout with text and ticks
  let xPos = -6.5; // Start position

  for (let i = 0; i < entries.length; i++) {
    // Gap before entry
    xPos += gapSize;

    // Add text
    const text = ctx.fontAtlas.createText(entries[i], {
      fontSize: 13,
      color: colors.paper,
      align: 'center'
    });
    text.position.set(xPos, 0, 0);
    contentGroup.add(text);

    // Estimate text width: approximately 0.07 units per character
    const textWidth = entries[i].length * 0.07;
    xPos += textWidth;

    // Gap after entry
    xPos += gapSize;

    // Add separator tick (not after last entry)
    if (i < entries.length - 1) {
      const tickGeom = new THREE.PlaneGeometry(tickWidth, tickHeight);
      const tick = new THREE.Mesh(tickGeom, tickMat);
      tick.position.set(xPos, 0, 0);
      contentGroup.add(tick);
      xPos += tickWidth;
    }
  }

  // Add trailing gap
  xPos += gapSize;
  const stripLength = xPos;

  // === SEAMLESS LOOP ===
  const scrollGroup = new Group();
  scrollGroup.add(contentGroup);

  // Clone content for second iteration
  const contentClone = contentGroup.clone();
  contentClone.position.x = stripLength;
  scrollGroup.add(contentClone);

  group.add(scrollGroup);

  // === APPLY FLY-THROUGH PRIMITIVE ===
  const primitiveResult = ctx.primitives['fly-through'](scrollGroup, {
    speed: 0.4, // 0.4 scene units/sec leftward
    depthUnits: 0,
    trigger: 'time'
  });

  // === CLEANUP ===
  group.userData.cleanup = () => {
    if (primitiveResult?.cleanup) primitiveResult.cleanup();
    ribbonGeom.dispose();
    ribbonMat.dispose();
    tickMat.dispose();
  };

  group.userData.handlers = {};

  return group;
}
